CREATE OR REPLACE PROCEDURE sp(
  para_Major NUMBER,
  para_Sex VARCHAR2,
  para_ResTypeID NUMBER,
  para_ResTypeName VARCHAR2,
  para_Rating NUMBER
) AS
  temp_num NUMBER := 0;
  temp_text VARCHAR2(4000) := '';
  row_count NUMBER := 0;
  flag NUMBER := 0;
  cur SYS_REFCURSOR;
  CURSOR c_restype (
    p_ResTypeID NUMBER,
    p_ResTypeName VARCHAR2
  ) IS
  SELECT "ResTypeID", "ResTypeName"
  FROM "Restaurant_Type"
  WHERE "ResTypeID" > p_ResTypeID
    AND "ResTypeName" LIKE p_ResTypeName
  FOR UPDATE;
  v_ResTypeID NUMBER;
  v_ResTypeName VARCHAR2(4000);
  v_Rating NUMBER;
  v_Major NUMBER;
  v_Sex VARCHAR2(4000);
BEGIN
  temp_num := 0;
  temp_text := '';
  row_count := 0;
  flag := 0;

  IF para_Major < 10 THEN
    UPDATE "Student" SET "Sex" = 'INACTIVE' WHERE "Major" < para_Major;
    flag := 1;
  ELSIF para_Major < 25 THEN
    OPEN c_restype(para_ResTypeID, para_ResTypeName);
    flag := 2;
  ELSIF para_Major < 40 THEN
    OPEN cur FOR SELECT "Rating" FROM "Restaurant" WHERE "Rating" BETWEEN para_Rating AND para_Rating * 2;
    flag := 3;
  ELSE
    OPEN cur FOR SELECT "Major", "Sex" FROM "Student" WHERE "Major" > TRUNC(para_Major / 2);
    flag := 4;
  END IF;

  IF flag = 2 THEN
    LOOP
      FETCH c_restype INTO v_ResTypeID, v_ResTypeName;
      EXIT WHEN c_restype%NOTFOUND;
      row_count := row_count + 1;
      IF v_ResTypeID < 50 THEN
        UPDATE "Restaurant_Type" SET "ResTypeName" = 'COMPLETED' WHERE CURRENT OF c_restype;
      ELSE
        temp_num := temp_num + v_ResTypeID;
      END IF;
    END LOOP;
    CLOSE c_restype;
  ELSIF flag = 3 THEN
    LOOP
      FETCH cur INTO v_Rating;
      EXIT WHEN cur%NOTFOUND;
      row_count := row_count + 1;
      IF v_Rating > 100 THEN
        temp_text := 'OVER_LIMIT';
      ELSIF v_Rating > 50 THEN
        temp_text := 'WITHIN_RANGE';
      ELSE
        temp_text := 'BELOW_MIN';
      END IF;
    END LOOP;
    CLOSE cur;
  ELSIF flag = 4 THEN
    LOOP
      FETCH cur INTO v_Major, v_Sex;
      EXIT WHEN cur%NOTFOUND;
      row_count := row_count + 1;
      IF MOD(v_Major, 2) = 0 THEN
        temp_num := temp_num + 1;
      END IF;
    END LOOP;
    CLOSE cur;
  END IF;

  IF flag = 1 THEN
    DELETE FROM "Restaurant_Type" WHERE "ResTypeID" < para_ResTypeID;
    IF para_Sex = 'M' THEN
      UPDATE "Restaurant" SET "Rating" = "Rating" - 1 WHERE "Rating" < para_Rating;
    END IF;
  ELSIF flag = 2 AND temp_num > 100 THEN
    UPDATE "Restaurant" SET "Rating" = "Rating" - 10 WHERE "Rating" > 200;
  ELSIF flag = 3 AND temp_text = 'OVER_LIMIT' THEN
    DELETE FROM "Restaurant" WHERE "Rating" > 150;
  ELSIF flag = 4 AND temp_num > 5 THEN
    UPDATE "Student" SET "Sex" = 'PROCESSED' WHERE "Major" < para_Major AND "Sex" = para_Sex;
  ELSE
    UPDATE "Restaurant_Type" SET "ResTypeName" = 'DEFAULT' WHERE "ResTypeID" IS NULL;
  END IF;
END;

